def cached(
    cache, key=keys.hashkey, lock=None, condition=None, info=False, *, cache_if=None
):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    If cache_if is not None, it is called with each result computed on a
    cache miss before insertion. False results skip insertion; exceptions
    propagate without caching the result. Cache hits do not call cache_if.
    With cache=None, cache_if is not called.

    """
    from ._cached import _wrapper

    def decorator(func):
        if info:
            if isinstance(cache, Cache):

                def make_info(hits, misses):
                    return _CacheInfo(hits, misses, cache.maxsize, cache.currsize)

            elif isinstance(cache, collections.abc.Mapping):

                def make_info(hits, misses):
                    return _CacheInfo(hits, misses, None, len(cache))

            else:

                def make_info(hits, misses):
                    return _CacheInfo(hits, misses, 0, 0)

            return _wrapper(
                func, cache, key, lock, condition, info=make_info, cache_if=cache_if
            )
        else:
            return _wrapper(func, cache, key, lock, condition, cache_if=cache_if)

    return decorator


